#import <Cocoa/Cocoa.h>
#import <WebKit/WebKit.h>
#import <Photos/Photos.h>
@interface StudioDelegate:NSObject<NSApplicationDelegate,WKNavigationDelegate,WKUIDelegate,WKScriptMessageHandler>
@property NSWindow*window;@property WKWebView*web;@property NSTask*server;@property NSString*workspace;@property BOOL syncing;@property BOOL cancelSync;@property BOOL publishing;@property BOOL draftDirty;
@end
@implementation StudioDelegate
-(void)applicationDidFinishLaunching:(NSNotification*)note{
 self.workspace=[NSBundle.mainBundle objectForInfoDictionaryKey:@"StudioWorkspace"];
 NSMenu*menu=[NSMenu new];NSMenuItem*appItem=[NSMenuItem new];NSMenu*appMenu=[NSMenu new];[appMenu addItemWithTitle:@"Quit Sam Benari Studio" action:@selector(terminate:) keyEquivalent:@"q"];appItem.submenu=appMenu;[menu addItem:appItem];NSMenuItem*edit=[NSMenuItem new];NSMenu*editMenu=[[NSMenu alloc]initWithTitle:@"Edit"];[editMenu addItemWithTitle:@"Undo" action:@selector(undo:) keyEquivalent:@"z"];[editMenu addItem:[NSMenuItem separatorItem]];[editMenu addItemWithTitle:@"Cut" action:@selector(cut:) keyEquivalent:@"x"];[editMenu addItemWithTitle:@"Copy" action:@selector(copy:) keyEquivalent:@"c"];[editMenu addItemWithTitle:@"Paste" action:@selector(paste:) keyEquivalent:@"v"];[editMenu addItemWithTitle:@"Select All" action:@selector(selectAll:) keyEquivalent:@"a"];edit.submenu=editMenu;[menu addItem:edit];NSApp.mainMenu=menu;
 self.window=[[NSWindow alloc]initWithContentRect:NSMakeRect(0,0,MIN(1380,NSScreen.mainScreen.visibleFrame.size.width-60),MIN(920,NSScreen.mainScreen.visibleFrame.size.height-60)) styleMask:NSWindowStyleMaskTitled|NSWindowStyleMaskClosable|NSWindowStyleMaskMiniaturizable|NSWindowStyleMaskResizable backing:NSBackingStoreBuffered defer:NO];self.window.title=@"Sam Benari Studio";self.window.minSize=NSMakeSize(800,650);[self.window center];
 WKWebViewConfiguration*config=[WKWebViewConfiguration new];[config.userContentController addScriptMessageHandler:self name:@"studio"];self.web=[[WKWebView alloc]initWithFrame:self.window.contentView.bounds configuration:config];self.web.autoresizingMask=NSViewWidthSizable|NSViewHeightSizable;self.web.navigationDelegate=self;self.web.UIDelegate=self;self.window.contentView=self.web;[self.window makeKeyAndOrderFront:nil];[NSApp activateIgnoringOtherApps:YES];
 [self.web loadHTMLString:@"<html><body style='font:16px -apple-system;background:#f7f7f4;padding:80px;color:#444'><h1 style='font-weight:300'>Opening your studio…</h1><p>Your photographs stay on this Mac.</p></body></html>" baseURL:nil];[self checkServer:0];
}
-(void)alert:(NSString*)message{dispatch_async(dispatch_get_main_queue(),^{NSAlert*a=[NSAlert new];a.messageText=@"Sam Benari Studio";a.informativeText=message;[a runModal];});}
-(void)trace:(NSString*)text{@synchronized(self){NSString*file=[self.workspace stringByAppendingPathComponent:@"data/studio-app.log"];[NSFileManager.defaultManager createDirectoryAtPath:file.stringByDeletingLastPathComponent withIntermediateDirectories:YES attributes:nil error:nil];if(![NSFileManager.defaultManager fileExistsAtPath:file])[NSFileManager.defaultManager createFileAtPath:file contents:nil attributes:nil];NSFileHandle*h=[NSFileHandle fileHandleForWritingAtPath:file];[h seekToEndOfFile];[h writeData:[[NSString stringWithFormat:@"%@ %@\n",NSDate.date,text]dataUsingEncoding:NSUTF8StringEncoding]];[h closeFile];}}
-(void)checkServer:(NSInteger)attempt{
 [self trace:[NSString stringWithFormat:@"Checking local service %ld",(long)attempt]];NSURL*url=[NSURL URLWithString:@"http://127.0.0.1:4173/api/health"];NSMutableURLRequest*r=[NSMutableURLRequest requestWithURL:url];r.timeoutInterval=2;
 NSURLSessionConfiguration*sessionConfig=NSURLSessionConfiguration.ephemeralSessionConfiguration;sessionConfig.connectionProxyDictionary=@{};sessionConfig.timeoutIntervalForRequest=2;sessionConfig.timeoutIntervalForResource=3;NSURLSession*session=[NSURLSession sessionWithConfiguration:sessionConfig];[[session dataTaskWithRequest:r completionHandler:^(NSData*data,NSURLResponse*response,NSError*error){[self trace:[NSString stringWithFormat:@"Health response %@ %@",error.localizedDescription?:@"OK",data?[[NSString alloc]initWithData:data encoding:NSUTF8StringEncoding]:@"No data"]];[session finishTasksAndInvalidate];NSDictionary*j=data?[NSJSONSerialization JSONObjectWithData:data options:0 error:nil]:nil;dispatch_async(dispatch_get_main_queue(),^{
  if([j[@"app"] isEqual:@"sam-benari-studio"]){[self trace:@"Opening manager"];[self.web loadRequest:[NSURLRequest requestWithURL:[NSURL URLWithString:@"http://127.0.0.1:4173/manage"]]];return;}
  if(!error&&response){[self alert:@"Another application is using the studio’s local address. Close the older local preview and open this app again."];return;}
  if(attempt==0){NSString*resources=NSBundle.mainBundle.resourcePath;NSTask*t=[NSTask new];t.executableURL=[NSURL fileURLWithPath:[resources stringByAppendingPathComponent:@"bin/node"]];t.arguments=@[[resources stringByAppendingPathComponent:@"Studio/server.mjs"]];t.currentDirectoryURL=[NSURL fileURLWithPath:self.workspace];NSMutableDictionary*env=[NSProcessInfo.processInfo.environment mutableCopy];env[@"STUDIO_WORKSPACE"]=self.workspace;env[@"STUDIO_TOOLS"]=[resources stringByAppendingPathComponent:@"bin/photo-tools"];env[@"PATH"]=@"/usr/bin:/bin:/usr/sbin:/sbin:/usr/local/bin:/opt/homebrew/bin";t.environment=env;NSString*log=[self.workspace stringByAppendingPathComponent:@"data/studio-server.log"];[NSFileManager.defaultManager createDirectoryAtPath:log.stringByDeletingLastPathComponent withIntermediateDirectories:YES attributes:nil error:nil];[NSFileManager.defaultManager createFileAtPath:log contents:nil attributes:nil];NSFileHandle*handle=[NSFileHandle fileHandleForWritingAtPath:log];t.standardOutput=handle;t.standardError=handle;NSError*launchError=nil;if(![t launchAndReturnError:&launchError]){[self alert:launchError.localizedDescription];return;}self.server=t;}
