  dispatch_after(dispatch_time(DISPATCH_TIME_NOW,NSEC_PER_MSEC*300),dispatch_get_main_queue(),^{[self checkServer:attempt+1];});
 });}]resume];
}
-(void)webView:(WKWebView*)web didFinishNavigation:(WKNavigation*)navigation{[self trace:[NSString stringWithFormat:@"Loaded %@",web.URL.absoluteString]];}
-(void)webView:(WKWebView*)web didFailProvisionalNavigation:(WKNavigation*)navigation withError:(NSError*)error{[self trace:error.localizedDescription];if(error.code!=-999)[self alert:@"The studio page could not open. Please reopen the app. Your library is safe."];}
-(BOOL)applicationShouldTerminateAfterLastWindowClosed:(NSApplication*)sender{return YES;}
-(NSApplicationTerminateReply)applicationShouldTerminate:(NSApplication*)sender{if(self.publishing){[self alert:@"Your website update is still running. Keep the studio open until publishing finishes."];return NSTerminateCancel;}if(self.draftDirty){NSAlert*a=[NSAlert new];a.messageText=@"You have unsaved draft edits.";a.informativeText=@"Save your draft before closing the studio, or discard the unsaved edits.";[a addButtonWithTitle:@"Keep editing"];[a addButtonWithTitle:@"Discard edits and quit"];if([a runModal]==NSAlertFirstButtonReturn)return NSTerminateCancel;}if(self.syncing){NSAlert*a=[NSAlert new];a.messageText=@"A photo sync is running.";a.informativeText=@"Quit now and finish importing the remaining photographs the next time you sync?";[a addButtonWithTitle:@"Keep syncing"];[a addButtonWithTitle:@"Quit"];if([a runModal]==NSAlertFirstButtonReturn)return NSTerminateCancel;self.cancelSync=YES;}return NSTerminateNow;}
-(void)applicationWillTerminate:(NSNotification*)note{if(self.server.running)[self.server terminate];}
-(void)webView:(WKWebView*)web decidePolicyForNavigationAction:(WKNavigationAction*)action decisionHandler:(void(^)(WKNavigationActionPolicy))handler{NSURL*u=action.request.URL;[self trace:[NSString stringWithFormat:@"Navigation %@",u.absoluteString]];BOOL local=([u.host isEqual:@"127.0.0.1"]&&u.port.intValue==4173);if([u.scheme isEqual:@"about"]){handler(WKNavigationActionPolicyAllow);return;}if(local&&(!action.targetFrame||!action.targetFrame.isMainFrame||[u.path hasPrefix:@"/manage"])){handler(WKNavigationActionPolicyAllow);return;}if(u){[NSWorkspace.sharedWorkspace openURL:u];handler(WKNavigationActionPolicyCancel);}else handler(WKNavigationActionPolicyAllow);}
-(WKWebView*)webView:(WKWebView*)web createWebViewWithConfiguration:(WKWebViewConfiguration*)config forNavigationAction:(WKNavigationAction*)action windowFeatures:(WKWindowFeatures*)features{if(action.request.URL)[NSWorkspace.sharedWorkspace openURL:action.request.URL];return nil;}
-(void)webView:(WKWebView*)web runOpenPanelWithParameters:(WKOpenPanelParameters*)parameters initiatedByFrame:(WKFrameInfo*)frame completionHandler:(void(^)(NSArray<NSURL*>*))completion{NSOpenPanel*p=[NSOpenPanel openPanel];p.canChooseDirectories=NO;p.canChooseFiles=YES;p.allowsMultipleSelection=parameters.allowsMultipleSelection;[p beginSheetModalForWindow:self.window completionHandler:^(NSModalResponse result){completion(result==NSModalResponseOK?p.URLs:nil);}];}
-(void)notify:(NSDictionary*)message{NSData*data=[NSJSONSerialization dataWithJSONObject:message options:0 error:nil];NSString*json=[[NSString alloc]initWithData:data encoding:NSUTF8StringEncoding];dispatch_async(dispatch_get_main_queue(),^{[self.web evaluateJavaScript:[NSString stringWithFormat:@"window.dispatchEvent(new CustomEvent('studio-photos-sync',{detail:%@}));",json] completionHandler:nil];});}
-(void)userContentController:(WKUserContentController*)controller didReceiveScriptMessage:(WKScriptMessage*)message{if(![message.frameInfo.securityOrigin.host isEqual:@"127.0.0.1"]||message.frameInfo.securityOrigin.port!=4173)return;if(![message.body isKindOfClass:NSDictionary.class])return;if([message.body[@"action"] isEqual:@"draftStatus"]){self.draftDirty=[message.body[@"dirty"] boolValue];return;}if([message.body[@"action"] isEqual:@"publishingStatus"]){self.publishing=[message.body[@"active"] boolValue];return;}if([message.body[@"action"] isEqual:@"syncPhotos"])[self syncPhotos];}
-(void)syncPhotos{if(self.syncing)return;self.syncing=YES;self.cancelSync=NO;[PHPhotoLibrary requestAuthorizationForAccessLevel:PHAccessLevelReadWrite handler:^(PHAuthorizationStatus status){if(status!=PHAuthorizationStatusAuthorized&&status!=PHAuthorizationStatusLimited){self.syncing=NO;[self notify:@{@"status":@"error",@"message":@"Allow Photos access for Sam Benari Studio in System Settings to sync the album. You can also import files directly."}];return;}dispatch_async(dispatch_get_global_queue(QOS_CLASS_USER_INITIATED,0),^{[self exportAlbum];});}];}
-(void)exportAlbum{
 NSMutableArray<PHAsset*>*assets=[NSMutableArray array];NSMutableSet*seen=[NSMutableSet set];PHFetchResult*albums=[PHAssetCollection fetchAssetCollectionsWithType:PHAssetCollectionTypeAlbum subtype:PHAssetCollectionSubtypeAny options:nil];
 for(PHAssetCollection*album in albums){NSString*name=[[album.localizedTitle lowercaseString] stringByReplacingOccurrencesOfString:@" " withString:@""];if(![name isEqual:@"streetphotorgraphy"]&&![name isEqual:@"streetphotography"])continue;PHFetchOptions*options=[PHFetchOptions new];options.predicate=[NSPredicate predicateWithFormat:@"mediaType == %d",PHAssetMediaTypeImage];options.sortDescriptors=@[[NSSortDescriptor sortDescriptorWithKey:@"creationDate" ascending:NO]];PHFetchResult*items=[PHAsset fetchAssetsInAssetCollection:album options:options];for(PHAsset*a in items)if(![seen containsObject:a.localIdentifier]){[assets addObject:a];[seen addObject:a.localIdentifier];}}
 if(!assets.count){self.syncing=NO;[self notify:@{@"status":@"error",@"message":@"The Street Photography album was not found in Photos, or access is limited. Allow access to that album, or import photographs from files."}];return;}
 NSString*dir=[self.workspace stringByAppendingPathComponent:@"data/photos-inbox"];[NSFileManager.defaultManager createDirectoryAtPath:dir withIntermediateDirectories:YES attributes:nil error:nil];NSString*indexPath=[self.workspace stringByAppendingPathComponent:@"data/photos-sync-index.json"];NSMutableDictionary*index=[[NSJSONSerialization JSONObjectWithData:[NSData dataWithContentsOfFile:indexPath]?:[NSData data] options:NSJSONReadingMutableContainers error:nil] mutableCopy]?:[NSMutableDictionary dictionary];NSMutableArray*manifest=[NSMutableArray array];NSInteger done=0,failures=0;
 for(PHAsset*asset in assets){@autoreleasepool{if(self.cancelSync)break;NSString*identifier=asset.localIdentifier,*stamp=[NSString stringWithFormat:@"%.3f",asset.modificationDate.timeIntervalSince1970];NSDictionary*old=index[identifier];NSString*pending=old[@"file"]?[dir stringByAppendingPathComponent:old[@"file"]]:nil;
  if([old[@"stamp"] isEqual:stamp]){if(pending&&[NSFileManager.defaultManager fileExistsAtPath:pending])[manifest addObject:@{@"id":identifier,@"file":old[@"file"],@"filename":old[@"filename"]}];done++;[self notify:@{@"status":@"exporting",@"completed":@(done),@"total":@(assets.count)}];continue;}
  PHImageRequestOptions*options=[PHImageRequestOptions new];options.networkAccessAllowed=YES;options.synchronous=YES;options.version=PHImageRequestOptionsVersionCurrent;options.deliveryMode=PHImageRequestOptionsDeliveryModeHighQualityFormat;__block NSData*bytes=nil;
  [[PHImageManager defaultManager]requestImageDataAndOrientationForAsset:asset options:options resultHandler:^(NSData*data,NSString*uti,CGImagePropertyOrientation orientation,NSDictionary*info){bytes=data;}];
  if(bytes){PHAssetResource*resource=[PHAssetResource assetResourcesForAsset:asset].firstObject;NSString*filename=resource.originalFilename?:@"Photograph.jpg";NSString*key=[[identifier componentsSeparatedByString:@"/"] firstObject];NSString*file=[key stringByAppendingPathExtension:@"img"];NSError*error=nil;if([bytes writeToFile:[dir stringByAppendingPathComponent:file] options:NSDataWritingAtomic error:&error]){[manifest addObject:@{@"id":identifier,@"file":file,@"filename":filename}];index[identifier]=@{@"stamp":stamp,@"file":file,@"filename":filename};}else failures++;}else failures++;
  done++;[self notify:@{@"status":@"exporting",@"completed":@(done),@"total":@(assets.count)}];}}
 NSData*manifestData=[NSJSONSerialization dataWithJSONObject:manifest options:0 error:nil];[manifestData writeToFile:[dir stringByAppendingPathComponent:@"manifest.json"] atomically:YES];[[NSJSONSerialization dataWithJSONObject:index options:0 error:nil]writeToFile:indexPath atomically:YES];self.syncing=NO;[self notify:@{@"status":@"ready",@"completed":@(done),@"total":@(assets.count),@"failures":@(failures)}];
}
@end
int main(int argc,const char*argv[]){@autoreleasepool{NSApplication*app=[NSApplication sharedApplication];StudioDelegate*delegate=[StudioDelegate new];app.delegate=delegate;[app setActivationPolicy:NSApplicationActivationPolicyRegular];[app run];}}
